INSERT INTO `gde_avaliacao_perguntas` (`id_pergunta`,`pergunta`,`tipo`) VALUES ('1','Gostaria de fazer outra disciplina com este(a) professor(a)?','p'),('2','O(A) professor(a) foi coerente?','t'),('3','O(A) professor(a) explicava bem?','t'),('4','Foi fácil passar nesta Disciplina?','t');
INSERT INTO `gde_disciplinas` (`id_disciplina`,`sigla`,`nome`,`creditos`,`nivel`,`periodicidade`,`parte`,`ementa`,`bibliografia`,`quinzenal`,`cursacoes`,`reprovacoes`,`max_reprovacoes`,`id_instituto`) VALUES ('837','CE151','Introdução à Economia','6','G','1','0','<p>A economia de mercado, origens e destino da produ&ccedil;&atilde;o. A circula&ccedil;&atilde;o numa economia de mercado. As rela&ccedil;&otilde;es econ&ocirc;micas internacionais. O setor p&uacute;blico. O sistema financeiro. A unidade produtora, sua inser&ccedil;&atilde;o no sistema. Reparti&ccedil;&atilde;o e apropria&ccedil;&atilde;o do produto social.</p>','<p>BIBLIOGRAFIA:</p>\r\n\r\n<p>Ao Iongo do desenvolvimento dos itens do programa ser&atilde;o indicadas obras espec&iacute;ficas e o curso ter&aacute;, como texto condutor, o livro de: CANO, Wilson.&nbsp;<em>Introdu&ccedil;&atilde;o &agrave;</em>&nbsp;<em>Economia,&nbsp;</em>Ed. UN ESP, S&atilde;o Paulo, 3a. edi&ccedil;&atilde;o, 2012.</p>','0','331','7','2','17'),('1327','EA078',' Micro e Minicomputadores: Hardware','4','G',NULL,'0','Introdução. Interligação entre módulos. Ligação com o barramento interno. Memória. Organização da memória. Microprocessador. Co-processadores e controladores. Entrada/Saída. Periféricos.',NULL,'0','731','75','3','9'),('1348','EA876','Introdução a Software de Sistema','4','G','5','0','<p>Montadores. Carregadores. Compiladores. Sistemas Operacionais.</p>','<p><span style=\"color:rgb(68, 68, 68)\">RICARTE, I.L.M. Introdu&ccedil;&atilde;o &agrave; Compila&ccedil;&atilde;o. Campus/Elsevier, 2008. ISBN 978-85-352-3067-3 TANENBAUM, A.S. Sistemas Operacionais Modernos, 2&ordf; edi&ccedil;&atilde;o. Person/Prentice-Hall, 2003. ISBN 978-85-87918-57-4</span></p>','0','569','28','3','9'),('1349','EA877','Micro e Minicomputadores: Software','4','G','5','0','<p>Introdu&ccedil;&atilde;o. Linguagem Assembly. Montadores. Linguagem Macro. Processador de Macro. Carregadores. Compiladores. Sistemas Operacionais.</p>','<p><span style=\"color:rgb(68, 68, 68)\">Apostila DONOVAN, J.J. Systems Programming McGraw?Hill, 1972(?). ULLMAN, J.D. Fundamental Concepts of Programming Systems Prentice?Hall., 1974. VELOSO, P. e outros Estruturas de Dados Ed. Campus, 1984. (ISSN 85-7001-167-9) SETZER, V. e outros A Constru&ccedil;&atilde;o de um compilador Ed. Campus, 1983. TANENBAUM, A.S. Modern Operating Systems Prentice-Hall International, 1992. (ISBN 0-13-595752-4)</span></p>','0','0','0','0',NULL),('1350','EA878',' Laboratório, Micro e  Minicomputadores: Software','2','G',NULL,'0','Experiências sobre montadores, máquinas, carregadores e sistemas operacionais.',NULL,'0','187','21','3','9'),('1395','EC306','Métodos Matemáticos em Engenharia Civil','6','G','1','0','<p>Equa&ccedil;&otilde;es diferenciais ordin&aacute;rias: tipos e m&eacute;todos de resolu&ccedil;&atilde;o. Aplica&ccedil;&otilde;es &agrave; Engenharia Civil: flex&atilde;o de vigas engastadas e biapoiadas, vigas sobre base el&aacute;stica, equa&ccedil;&atilde;o da linha el&aacute;stica, instabilidade de barras, estudo de vibra&ccedil;&otilde;es; fluxo em meios porosos e problemas de hidr&aacute;ulica. Sistemas de equa&ccedil;&otilde;es diferenciais. Equa&ccedil;&otilde;es diferenciais e parciais: separa&ccedil;&atilde;o de vari&aacute;veis. Condu&ccedil;&atilde;o de calor. Equa&ccedil;&atilde;o da onda.</p>','<p>N&atilde;o h&aacute;.</p>','0','61','4','3','8'),('1582','EE410','Introdução à Ciência dos Materiais para Engenharia Elétrica','4','G','5','0','<p>Estado s&oacute;lido. Propriedades mec&acirc;nicas dos s&oacute;lidos. Propriedades &oacute;pticas dos materiais. Propriedades magn&eacute;ticas. Propriedades t&eacute;rmicas. Propriedades el&eacute;tricas.</p>','<p><span style=\"color:rgb(68, 68, 68)\">SOLYMAR, D.W. Lectures on the Electrical Properties of Materials. Oxford University Press, 1995. CALLISTER Jr, W.D. Materials Science and Engineering, John Wiley &amp; Sons, 1997. HUMMEL, R.E. Electronic Properties of Materials, Springer Verlag, 1985. MAYER, J.W. &amp; LAU, S.S. Electronic Materials Science: for ICs in Si and GaAs. Macmillan, 1990.</span></p>','0','1086','182','2','9'),('1584','EE521','Introdução à Teoria Eletromagnética','4','G','5','0','<p>For&ccedil;a e campo eletrost&aacute;tico. Densidade de fluxo el&eacute;trico e lei de Gauss. Potencial eletrost&aacute;tico. Corrente estacion&aacute;ria. Condutor e Resist&ecirc;ncia. Diel&eacute;trico e capacit&acirc;ncia. Equa&ccedil;&otilde;es de Poisson e Laplace. Campo magnetost&aacute;tico. Campos vari&aacute;veis no tempo. For&ccedil;a em materiais magn&eacute;ticos indut&acirc;ncia. Sistemas de unidade.</p>','<p><span style=\"color:rgb(68, 68, 68)\">Livro texto: KRAUS, J.D. Eletromagnetics. 4th ed. McGraw-Hill, 1991. RAMO,S., WHINNERY,J.R. &amp; DUZER,T.V. Fields and Waves in Communication Electromagnetic. 3rd ed. JohnWiley &amp; Sons, 1994. Livros para consulta: REITZ, J.R., MILFORD,F.J. &amp;CHRISTY,R.W. Foundations of Electromagnetic Theory. 3rd Addison-Wesley, 1980. HAYT,W.H. Eletromagnetismo. Livros T&eacute;cnicos e Cient&iacute;ficos, 3a. edi&ccedil;&atilde;o, 1983. EDMINISTER, J.A. Eletromagnetismo. Cole&ccedil;&atilde;o Schaum, McGraw-Hill do Brasil, 1981. WHITTAKER, E. A History of the Theories of Acther &amp; Electricity. Vols. 1 e 2, D.Publications, 1989.</span></p>','0','1127','224','4','9'),('2096','EM330','Oficinas I','4','G','5','0','<p>Medidas lineares com instrumentos de medida direta e indireta. No&ccedil;&otilde;es de toler&acirc;ncia ISO. Tra&ccedil;agem de pe&ccedil;as, trabalhos de bancada. Opera&ccedil;&otilde;es b&aacute;sicas com m&aacute;quinas operatrizes, furadeira, plaina limadora, torno mec&acirc;nico horizontal e fresadora.<br />\r\nObs.: Realizado nas oficinas da Escola SENAI &quot;Roberto Mange&quot;, na Rua Pastor C&iacute;cero Canuto de Lima, 71 - S&atilde;o Bernardo - Campinas - SP.</p>','<p><strong>Refer&ecirc;ncias b&aacute;sicas:</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Apostila de Curso dada pelo docente</p>','0','2124','8','1','11'),('2588','ES572','Circuitos Lógicos','4','G','2','0','<p>Conceitos l&oacute;gicos. Circuitos b&aacute;sicos. Minimiza&ccedil;&atilde;o de fun&ccedil;&otilde;es Booleanas. Sistemas de numera&ccedil;&atilde;o. Aritm&eacute;tica bin&aacute;ria. C&oacute;digos. Circuitos &agrave; contato. S&iacute;ntese de circuitos combinacionais. Circuitos de mem&oacute;ria. Circuitos sequenciais. Projeto de circuitos sequenciais. M&aacute;quinas de Mealy e Moore. Projeto de contadores, decodificadores e multiplexadores. Temporizadores: monoest&aacute;veis, ast&aacute;veis e osciladores. Dispositivos l&oacute;gicos program&aacute;veis.</p>','<p>Refer&ecirc;ncias b&aacute;sicas:</p>\r\n\r\n<ul>\r\n	<li>Sistemas Digitais: Fundamentos e Aplica&ccedil;&otilde;es, Thomas L. Floyd, Bookman, 2007</li>\r\n	<li>Sistemas Digitais: Princ&iacute;pios e Aplica&ccedil;&otilde;es, Ronald J. Tocci, Neal S. Widmer, Gregory L. Moss, Pearson Prentice Hall, 10&ordf; &nbsp;Edi&ccedil;&atilde;o, 2007</li>\r\n	<li>Sistemas Digitais: uma Abordagem Integrada, John P. Uyemura, Thomson, 2002</li>\r\n	<li>Sistemas Digitais: Projeto, Otimiza&ccedil;&atilde;o e HDLs, Frank Vahid, Artman, 2007</li>\r\n	<li>S&iacute;tios da Internet fornecidos ao longo do curso</li>\r\n	<li>Notas de aulas</li>\r\n</ul>','0','331','27','1','11'),('2636','ET616','Eletrotécnica','4','G','2','0','<p>Revis&atilde;o de conceitos b&aacute;sicos. Elementos e leis de circuitos el&eacute;tricos. Circuitos monof&aacute;sicos e trif&aacute;sicos. Transformadores. M&aacute;quinas el&eacute;tricas rotivas.</p>','<p><span style=\"color:rgb(68, 68, 68)\">Barreto, G.; Castro Jr., C.A.;Murari, C.A.F.; Sato,F. - Cirtcuitos de Corrente Alternada, Oficina de Textos, 2012. YARO BURIAN JR. Circuitos El&eacute;tricos. C.A.CASTRO E M.R.TANAKA Circuitos de Corrente Alternada - um curso introdut&oacute;rio Editora UNICAMP Gray/Wallace Eletrot&eacute;cnica - Princ&iacute;pios e Aplica&ccedil;&otilde;es Ao Livro T&eacute;cnico S.A. Valkenburgh/Neville Eletricidade B&aacute;sica Ao Livro T&eacute;cnico S.A. Gussow Eletricidade B&aacute;sica Editora McGraw Hill. Arnold Fundamentos de Eletrot&eacute;cnica E.P.U. Arnold/Stehr M&aacute;quinas El&eacute;tricas E.P.U.</span></p>','0','237','49','7','9'),('2747','F 313','Mecânica Geral','4','G','2','0','<p>Fundamentos da mec&acirc;nica newtoniana. Est&aacute;tica e din&acirc;mica do ponto material. Sistemas de part&iacute;culas. Referenciais acelerados. Sistemas de for&ccedil;as aplicados a um corpo r&iacute;gido. Est&aacute;tica e din&acirc;mica dos corpos r&iacute;gidos. V&iacute;nculos, graus de liberdade, princ&iacute;pio dos trabalhos virtuais.<br />\r\nObs.: Os alunos do curso de F&iacute;sica n&atilde;o poder&atilde;o cursar esta disciplina.</p>','<p>Mec&ecirc;nica, K. Symoin, Ed. Campus, RJ</p>','0','1555','346','6','20'),('2763','F 589','Estrutura da Matéria','4','G','5','0','<p>Introdu&ccedil;&atilde;o &agrave; teoria da relatividade restrita. Radia&ccedil;&atilde;o t&eacute;rmica e o postulado de Planck. F&oacute;tons e as propriedades corpusculares da radia&ccedil;&atilde;o. Propriedades ondulat&oacute;rias das part&iacute;culas e o postulado de De Broglie. O &aacute;tomo de Bohr. Introdu&ccedil;&atilde;o &agrave; equa&ccedil;&atilde;o de Schr&ouml;dinger e solu&ccedil;&otilde;es de problemas unidimensionais. O &aacute;tomo de hidrog&ecirc;nio.<br />\r\nObs.: A autoriza&ccedil;&atilde;o AA200 n&atilde;o ser&aacute; aplicada aos alunos dos cursos de F&iacute;sica.</p>','<p><strong>- </strong>&ldquo;F&iacute;sica Qu&acirc;ntica&rdquo;,&nbsp; 4&ordf; edi&ccedil;&atilde;o - Robert Eisberg, Robert Resnick - Editora Campus Ltda.</p>','0','872','186','6','20'),('3151','GE504','Matemática (Geologia)','4','G','2','0','<p>Derivadas e diferenciais, integrais m&uacute;ltiplas, integrais de linha e de superf&iacute;cie. Conceitos e exerc&iacute;cios de matem&aacute;tica e computa&ccedil;&atilde;o visando complementar a forma&ccedil;&atilde;o dos ge&oacute;logos com os t&oacute;picos n&atilde;o cobertos pelas demais disciplinas do curso.</p>','<p>J. STEWART &ndash; C&aacute;lculo I e II. 5a Ed. Editora Thomson, 712p.<br />\nB. DEMIDOVITCH - Problemas e Exerc&iacute;cios de An&aacute;lise Matem&aacute;tica. 6a&nbsp; Editora Mir, 488p.</p>','0','207','22','1','21'),('3897','LA114','Alemão I','4','G','5','0','<p>Introdu&ccedil;&atilde;o ao alem&atilde;o como l&iacute;ngua estrangeira (n&iacute;vel A1.1 no Quadro Comum Europeu, dispon&iacute;vel no s&iacute;tio eletr&ocirc;nico do CEL). Compreens&atilde;o e express&atilde;o oral/escrita, &ecirc;nfase na compreens&atilde;o. Fomento da autonomia e consci&ecirc;ncia lingu&iacute;stica. Estruturas fundamentais da l&iacute;ngua e textos altamente convencionalizados. Uso integrado de tecnologias digitais, inclusive na avalia&ccedil;&atilde;o. Trabalho aut&ocirc;nomo, individual e/ou em grupo, via ambiente virtual.</p>','<p><strong>Refer&ecirc;ncias b&aacute;sicas</strong></p>\r\n\r\n<ul>\r\n	<li>Blaue Blume &ndash; Edi&ccedil;&atilde;o Brasileira. Editora da Unicamp, 2011.</li>\r\n	<li>LANGENSCHEIDT TASCHENW&Ouml;RTERBUCH PORTUGIESISCH. Munique: Langenscheidt, 2012.</li>\r\n	<li>Reimann, Monika: Gram&aacute;tica essencial do alem&atilde;o. S&atilde;o Paulo: EPU, 2004.</li>\r\n</ul>\r\n\r\n<p><strong>Refer&ecirc;ncias Complementares</strong></p>\r\n\r\n<ul>\r\n	<li><a href=\"http://www.ggte.unicamp.br/moodle/course/category.php?id=42\">http://www.ggte.unicamp.br/moodle/course/category.php?id=42</a></li>\r\n</ul>','0','1078','12','2','1'),('4088','MA151','Cálculo I','4','G','5','0','<p>Fun&ccedil;&otilde;es reais de uma vari&aacute;vel real. Limite. Continuidade. Derivada. Integral. T&eacute;cnicas de integra&ccedil;&atilde;o.</p>',NULL,'0','0','0','0',NULL),('4096','MA251','Cálculo II','4','G','5','0','<p>Fun&ccedil;&otilde;es reais de v&aacute;rias vari&aacute;veis reais: derivadas e diferenciais, m&aacute;ximos e m&iacute;nimos, integrais m&uacute;ltiplas, integrais de linha e de superf&iacute;cie (Green, Gauss, Stokes).</p>',NULL,'0','0','0','0',NULL),('4163','MC111','Introdução ao Processamento de Dados','4','G','5','0','<p>Primeiras no&ccedil;&otilde;es sobre algoritmos e programas. Introdu&ccedil;&atilde;o &agrave; programa&ccedil;&atilde;o em linguagem de alto n&iacute;vel.</p>',NULL,'0','0','0','0',NULL),('4172','MC426','Engenharia de Software','4','G','5','0','<p style=\"text-align:justify\">Paradigmas da Engenharia de Software. Processos de Software. Modelos de Processo de Software. Extra&ccedil;&atilde;o e Especifica&ccedil;&atilde;o de Requisitos. An&aacute;lise e Projeto de Sistemas de Software. Padr&otilde;es de Arquitetura e Padr&otilde;es de Projeto.</p>','<p>I. Sommerville, Software Engineering, Addison-Wesley, 10th Edition, 2015.</p>\r\n\r\n<p>R. S. Pressman and B. Maxim, Software Engineering: A Practitioner&rsquo;s Approach, 8th Edition, McGrow Hill, 2014. &nbsp;</p>\r\n\r\n<p>C. Larman, Applying UML and Patterns: An Introduction to Object-Oriented Analysis and Design and the Unified Process, Second Edition, Prentice-Hall, 2002.</p>\r\n\r\n<p>L. Bass, P. Clements &amp; R. Kazman, Software Architecture in Practice, Second Edition, AddisonWesley, 2003, SEI Series in Software Engineering.</p>\r\n\r\n<p>M. Shaw &amp; D. Garlan. Software Architecture: Perspectives on an Emerging Discipline, Prentice Hall, 1996. &nbsp;</p>\r\n\r\n<p>F. Buschmann et al., A System of Patterns: Pattern-Oriented Software Architecture, Wiley, 1996.</p>\r\n\r\n<p>E. Gamma et al., Design Patterns: Elements of Reusable Object-Oriented Software, Addison-Wesley, 1995.</p>','0','511','23','2','16'),('4177','MC504','Sistemas Operacionais','4','G','5','0','<p style=\"text-align: justify;\">Conceito de processos: concorr&ecirc;ncias, regi&otilde;es cr&iacute;ticas, escalonamento. Conceitos de espa&ccedil;os de endere&ccedil;amento e de gerenciamento de mem&oacute;ria virtual, pagina&ccedil;&atilde;o, segmenta&ccedil;&atilde;o. Sistemas de arquivos: hierarquia, prote&ccedil;&atilde;o, organiza&ccedil;&atilde;o, seguran&ccedil;a. Gerenciamento de Entrada/Sa&iacute;da. Estudos de caso.</p>','<ul>\r\n	<li>A. S. Tanenbaum, H. Bos, Modern Operating Systems, 4th edition, Pearson, 2014</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>A. Silberschatz, P. Galvin, G. Gagne, Operating Systems Concepts, 9th edition, Wiley, 2012</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>W. Stallings, Operating Systems: Internals and Design Principles, 8th edition, Pearson, 2014</li>\r\n	<li>Separatas indicadas pelo docente&nbsp;</li>\r\n</ul>','0','417','39','0','16'),('4178','MC505',' Laboratório de Sistemas Operacionais','3','G',NULL,'0','Projeto e implementação de um protótipo de sistema operacional enfocando aspectos básicos como multiprogramação, gerência de periféricos, gerência de arquivos.',NULL,'0','0','0','0',NULL),('4181','MC522',' Organização de Computadores','4','G',NULL,'0','Noções básicas sobre circuitos lógicos, memórias, unidades centrais de processamento. Endereçamento, barramento, interrupção, comunicações, interfaces e periféricos. Computadores típicos.',NULL,'0','118','12','2','16'),('4189','MC600',' Estudo  Comparativo  de  Linguagens  de Programação','4','G',NULL,'0','Linguagens e seus diferentes paradigmas de programação. Implementação. Estrutura de dados, de nomes, de controle e de tipos. Sintaxe e semântica.',NULL,'0','0','0','0',NULL),('4190','MC602','Circuitos Lógicos e Organização de Computadores','3','G','2','0',NULL,NULL,'0','278','40','0','16'),('4191','MC603',' Laboratório de Circuitos Lógicos','4','G',NULL,'0','Metodologia de projeto digital. Técnicas de projeto usando lógica programável. Características elétricas de circuitos digitais. Linguagem VHDL. Projeto e implementação de lógica combinacional: decodificadores e seletores. Flip-flops. Contadores. Circuitos aritméticos. Memórias. Projeto e implementação de lógica seqüencial.',NULL,'0','0','0','0',NULL),('4431','ME203','Estatística Elementar','4','G','2','0','<p>Conceitos b&aacute;sicos de probabilidade e estat&iacute;stica descritiva. Vari&aacute;veis aleat&oacute;rias. Principais distribui&ccedil;&otilde;es discretas e cont&iacute;nuas: Binomial, Hipergeom&eacute;trica, Poisson, Normal, t, F,&nbsp;qui-quadrado. Amostragem. Estima&ccedil;&atilde;o, teste de hip&oacute;tese e intervalo de confian&ccedil;a para m&eacute;dias, propor&ccedil;&otilde;es e vari&acirc;ncias. Regress&atilde;o e correla&ccedil;&atilde;o. An&aacute;lise de vari&acirc;ncia.</p>','<p>ABREU, Regina. CHAGAS, M&aacute;rio (orgs.). Mem&oacute;ria e Patrim&ocirc;nio: ensaios contempor&acirc;neos. Rio de Janeiro: Lamparina, 2009.</p>\n\n<p>ANDERSON, Benedict. Comunidades Imaginadas. S&atilde;o Paulo: Companhia das Letras, 2008.</p>\n\n<p>CHUVA, M&aacute;rcia. Os arquitetos da mem&oacute;ria: sociog&ecirc;nese das pr&aacute;ticas de preserva&ccedil;&atilde;o do patrim&ocirc;nio cultural no Brasil (1930-1940). Rio deJaneiro: ed. UFRJ, 2009.</p>\n\n<p>CASTRIOTA, Leonardo. Patrim&ocirc;nio Cultural: conceitos, pol&iacute;ticas e instrumentos. S&atilde;o Paulo: Annablume, 2009.</p>\n\n<p>CHOAY, Francoise. A alegoria do patrim&ocirc;nio. S&atilde;o Paulo: UNESCO, 2001. FARGE, Arlette. Lugares para a hist&oacute;ria. Belo Horizonte: Aut&ecirc;ntica,2011.</p>\n\n<p>OLIVEIRA, Lucia Lippi. Cultura &eacute; Patrim&ocirc;nio: um guia. Rio de Janeiro: FGV, 2009.</p>\n\n<p>SALVADORI, Maria &Acirc;ngela Borges. Hist&oacute;ria, Ensino e Patrim&ocirc;nio. Araraquara, SP: Junqueira &amp; Marin Ed','0','1703','268','5','22'),('4432','ME210','Probabilidade I','4','G','5','0','<p>Espa&ccedil;o de probabilidade. Axiomas de Kolmogorov, propriedades, independ&ecirc;ncia, probabilidade condicional, Teorema de Bayes. Espa&ccedil;os amostrais equiprov&aacute;veis. Espa&ccedil;os amostrais infinitos. Vari&aacute;veis e vetores aleat&oacute;rios discretos bi e tri dimensionais; distribui&ccedil;&otilde;es marginais, conjuntas e condicionais e independ&ecirc;ncia. Transforma&ccedil;&otilde;es. Momentos. Modelos: uniforme, binomial, geom&eacute;trica, binomial negativa, hipergeom&eacute;trica e Poisson. Fun&ccedil;&otilde;es geratrizes. Aproxima&ccedil;&atilde;o da binomial. Vari&aacute;veis aleat&oacute;rias cont&iacute;nuas, distribui&ccedil;&atilde;o, densidade e momentos. Modelos uniformes, exponencial e normal. Simula&ccedil;&otilde;es.</p>','<p>1. CHUNG, K. L. (1974); &quot;Elementary Probability Theory with Stochastic Processes&quot;, Springer-Verlag.<br />\r\n2. FELLER, W. (1968); &quot;An Introduction to Probability Theory and its Applications&quot;. 3th edition, Vol. 1, Wiley.&nbsp;<br />\r\n3. FISZ, M. (1963); &quot;Probability Theory and Mathematical Statistics&quot;, Wiley.&nbsp;<br />\r\n4. HOEL, P. G.; PORT, S. C. &amp; STONE, C. J. (1971); &quot;Introduction to Probability Theory&quot;, Houghton-Mifflin.&nbsp;<br />\r\n5. ROSS, S. (1994); &quot;A First Course in Probability&quot;. 4th edition, Prentice Hall.</p>','0','2345','706','5','22'),('4755','MS210','Complementos de Matemática','6','G','2','0','<p>Fun&ccedil;&otilde;es de v&aacute;rias vari&aacute;veis: derivadas parciais e m&aacute;ximos e m&iacute;nimos. Integrais m&uacute;ltiplas e integrais de linha: independ&ecirc;ncia do caminho, teoremas de Green, Gauss e Stokes. Sequ&ecirc;ncias e s&eacute;ries: crit&eacute;rios de converg&ecirc;ncia, converg&ecirc;ncia uniforme, s&eacute;ries de pot&ecirc;ncia e s&eacute;ries de Fourier. Equa&ccedil;&otilde;es diferenciais ordin&aacute;rias: problema de valor inicial, equa&ccedil;&otilde;es lineares e solu&ccedil;&otilde;es por s&eacute;ries.</p>','<p>N. Piskunov, C&aacute;lculo Diferencial e Integral, Ed. Mir (tradu&ccedil;&atilde;o em portugu&ecirc;s)</p>\r\n\r\n<p>Boyce Di Prima, Equa&ccedil;&otilde;es Diferenciais Ordin&aacute;rias Elementares e Problemas de Valores de Contorno.</p>','0','32','0','1',NULL),('4761','MS328','Matemática Discreta','4','G','2','0',NULL,NULL,'0','378','87','3','22'),('6224','F 118',' Física I','4','G',NULL,'0','Cinemática do ponto. Leis de Newton. Estática e dinâmica da partícula. Trabalho e energia. Conservação de energia. Momento linear e sua conservação. Colisões. Momento angular da partícula e de sistema de partículas. Rotação de corpos rígidos.',NULL,'0','0','0','0',NULL),('6455','F 218',' Física II','4','G',NULL,'0','Oscilações. Gravitação. Ondas em meios elásticos. Ondas sonoras. Hidrostática e Hidrodinâmica. Viscosidade. Temperatura. Calorimetria e condução de calor. Leis da Termodinâmica. Teoria Cinética dos gases.',NULL,'0','0','0','0',NULL),('6456','F 318',' Física III','4','G',NULL,'0','Lei de Coulomb, Campo Elétrico, Lei de Gauss, Potencial Elétrico, Capacitância, Corrente e Resistência, Força Eletromotriz e Circuitos Elétricos, Campo Magnético, Lei de Ampère, Lei da Indução de Faraday, Indutância, Propriedades Magnéticas da Matéria, Oscilações Eletromagnéticas, Correntes Alternadas, Equações de Maxwell.',NULL,'0','0','0','0',NULL),('6472','AL008','Altern.:Lab.Sist.Computacionais:Hardware','2','G',NULL,'0',NULL,NULL,'0','0','0','0',NULL),('6473','AL009','Altern.:Redes de Computadores','4','G',NULL,'0',NULL,NULL,'0','0','0','0',NULL),('6768','MC302','Programação Orientada a Objetos','6','G','5','0','<p>Conceitos b&aacute;sicos e avan&ccedil;ados de programa&ccedil;&atilde;o orientada a objetos. Aplica&ccedil;&atilde;o dos conceitos usando uma linguagem orientada a objetos.</p>','<p>- The Java Programming Language, Ken Arnold, James Gosling, &amp; David Holmes; Prentice Hall, 4th edition (2005)</p>\n\n<p>- Java in a Nutshell, David Flanagan; O&#39;Reilly &amp; Associates, 5th edition (2005)</p>\n\n<p>- Thinking in Java, Bruce Eckel; Prentice Hall, 4th edition (2006)</p>\n\n<p>- Head First Java, Kathy Sierra &amp; Bert Bates; O&#39;Reilly Media, 2nd edition (2005)</p>\n\n<p>- Java How to Program, Harvey M. Deitel &amp; Paul J. Deitel; Prentice Hall, 7th edition (2007)</p>\n\n<p>- Object-Oriented Programming with Java: An Introduction, David J. Barnes; Prentice Hall (2000)</p>','0','834','57','0','16'),('6773','MC346','Paradigmas de Programação','4','G','5','0',NULL,NULL,'0','319','44','0','16'),('6779','EA872','Laboratório de Programação de Software Básico','2','G','2','0','<p>Experi&ecirc;ncias sobre montadores,&nbsp; carregadores, compiladores e sistemas operacionais.</p>','<p><span style=\"color:rgb(68, 68, 68)\">MCF52223 ColdFire(R) Integrated Microcontroller Reference Manual, Freescale Semiconductor. ColdFire Family Programmer&acute;s Reference Manual, Freescale Semiconductor. Cold Warrior Development Studio - IDE 5.6 Windows Automation Guide. Cold Warrior Development Studio - Assembler Reference. Code Warrior Development Stuido - IDE 5.7 User&acute;s Guide. Code Warrior Development Studio - Assembler Reference fo ColdFire Processors. Code Warrior Development Studio - Architectures Edition - Build Tools. Code Warrior Development Studio - ColdFire Assembler - Manual for Microcontrollers. Code Warrior Development Tools - C Compilers - Reference 3.2. Code Warrior Development Tools - IDE 5.7 Windows Automation Guide.</span></p>','0','108','23','0','9'),('8754','LA092','Língua Inglesa II','3','G','5','0','<!--[if gte mso 9]><xml>  <w:WordDocument>   <w:View>Normal</w:View>   <w:Zoom>0</w:Zoom>   <w:HyphenationZone>21</w:HyphenationZone>   <w:DoNotOptimizeForBrowser/>  </w:WordDocument> </xml><![endif]-->Considerando-se as propostas oficiais para o ensino da língua inglesa no âmbito do ensino médio e buscando articulá-las e expandi-las às especificidades do campo universitário, o curso tem como objetivo central ampliar o ensino da língua inglesa nesse contexto, ampliando-se o escopo para além dos objetivos gramaticais e estritamente instrumentais do idioma e focalizando-se o desenvolvimento linguístico, cultural e educacional do aluno.',NULL,'0','559','24','0','1'),('9197','MC322','Programação Orientada a Objetos','4','G','5','0','<p style=\"text-align:justify\">Conceitos b&aacute;sicos e avan&ccedil;ados de programa&ccedil;&atilde;o orientada a objetos. Aplica&ccedil;&atilde;o dos conceitos usando uma linguagem orientada a objetos.</p>','<p>1. Java: Como Programar, Paul Deitel &amp; Heivey Deitel, Pearson, 8a. Ed, 2010;<br />\r\n2. Java in a Nutshell, David Flanagan, O&rsquo;Reilley, 6th. Ed, 2014;<br />\r\n3. The Java Programming Language, Ken Arnold, James Gosling, &amp; David Holmes; Prentice Hall, 4th edition (2005);<br />\r\n4. Thinking in Java, Bruce Eckel; Prentice Hall, 2th edition (2000);<br />\r\n5. Data Structures and Algorithms with Object Oriented Design Patterns in Java, Bruno Preiss;<br />\r\n6. The Java Tutorials (Oracle) (http://docs.oracle.com/javase/tutorial/);<br />\r\n7. Java Pocket Guide - Robert Liguori &amp; Patricia Liguori; O&rsquo;Reilley, 2008;<br />\r\n8. Guia do Usu&aacute;rio UML, Grady Booch et. al.; Campus(1999).</p>','0','87','9','0','16'),('9223','LA094','Língua Inglesa IV','3','G','2','0','<p>Expandindo as orienta&ccedil;&otilde;es curriculares do Ensino M&eacute;dio &agrave;s especificidades da educa&ccedil;&atilde;o superior, a disciplina amplia conte&uacute;dos da LA093 nos dom&iacute;nios lingu&iacute;stico-discursivo, sociocultural e educacional e prioriza a reflex&atilde;o sobre o ensino superior, pesquisa, cidadania ativa e suas rela&ccedil;&otilde;es com o ingl&ecirc;s na sociedade globalizada, atrav&eacute;s de pr&aacute;ticas de letramentos digitais e cr&iacute;ticos, articuladas &agrave;s bases discursivas e textuais de narra&ccedil;&atilde;o, express&atilde;o de opini&atilde;o, argumenta&ccedil;&atilde;o e reivindica&ccedil;&atilde;o, envolvendo g&ecirc;neros orais, escritos e multimodais oriundos, prioritariamente, das esferas do entretenimento, da divulga&ccedil;&atilde;o cient&iacute;fica, al&eacute;m da pol&iacute;tica, acad&ecirc;mica, jornal&iacute;stica e multimidi&aacute;tica.</p>','<p>BAKHTIN, M. M. <em>Quest&otilde;es de Literatura e de Est&eacute;tica</em> (A Teoria do Romance). S&atilde;o Paulo: Editora Hucitec, 1988 [1934-1935].</p>\r\n\r\n<p>_________. Est&eacute;tica da Cria&ccedil;&atilde;o Verbal. S&atilde;o Paulo: Martins Fontes, 2003 [1979].</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>BAKHTIN, M. M./Voloch&iacute;nov, V. N. <em>Marxismo e filosofia da linguagem</em>. S&atilde;o Paulo: Hucitec, 2004 [1929].</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>BOLOGNINI, C. (Org.). <em>Discurso e Ensino</em>: O cinema na Escola. Campinas: Mercado de Letras, 2007.<a name=\"_GoBack\"></a></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>BOLOGNINI, C. (Org.). <em>Discurso e Ensino</em>: A l&iacute;ngua Inglesa na Escola. Campinas: Mercado de Letras, 2008.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>BOLOGNINI, C.; PFIFFER, C; LAGAZZI, S (Orgs.). <em>Discurso e Ensino</em>: Pr&aacute;ticas de Linguagem na Escola. Campinas: Mercado de Letras, 2009.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>BRASIL, SEB/MEC. Orienta&ccedil;&otilde;es Curriculares para o Ensino M&eacute;dio: linguagens, c&oacute;digos e suas tecnologias. Bras&iacute;lia, DF: SEB/MEC, 2006.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>COPE, B.; KALANTZIS, M. (Eds.). <em>Multiliteracies: Literacy Learning and the Design of Social Futures</em>. London: Routledge, 2000.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>CRYSTAL, D. <em>English as a global language</em>. Cambridge: Cambridge University Press, 1997.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>MONTE M&Oacute;R, W. Foreign languages teaching, education and the New Literacies Studies: expanding views. In: GON&Ccedil;ALVES, G. R; ALMEIDA, S. R. G.; PAIVA, V. L. O.; RODRIGUEZ-J&Uacute;NIOR, A. S. (Orgs.). <em>New Challenges in Language and Literature</em>. Belo Horizonte: Faculdade de Letras de UFMG, 2009. p. 177-189.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>ROCHA, C. R. <em>Reflex&otilde;es e propostas sobre ingl&ecirc;s no Ensino Fundamental I</em>: multiletramentos, plurilinguismo e transculturalidade. Campinas: Pontes Editores, 2012.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Webliografia de apoio</strong></p>\r\n\r\n<p>www.bbc.co.uk</p>\r\n\r\n<p>www.chronicle.com</p>\r\n\r\n<p>www.economist.co.</p>\r\n\r\n<p>www.newyorktimes.com</p>\r\n\r\n<p>www.the-scientist.com</p>\r\n\r\n<p>www.newscientist.com</p>\r\n\r\n<p><a href=\"http://www.youtube.com\">www.youtube.com</a></p>','0','337','9','0','1'),('9726','EB102','Geometria Analítica e Álgebra Linear','6','G','5','0','<p>Matrizes, Sistemas Lineares e Determinantes. Espa&ccedil;os Vetoriais de Dimens&atilde;o Finita. Produto Escalar e Vetorial. Retas e Planos. Proje&ccedil;&atilde;o Ortogonal. Dist&acirc;ncias. Transforma&ccedil;&otilde;es Lineares, Autovalores e Autovetores. Diagonaliza&ccedil;&atilde;o. Classifica&ccedil;&atilde;o das C&ocirc;nicas.</p>','<p>Refer&ecirc;ncias b&aacute;sicas:<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Anton, H., Rorres, C. &Aacute;lgebra Linear com Aplica&ccedil;&otilde;es. Bookman: Porto Alegre, RS. 2012.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Boldrini, J.L., et al. &Aacute;lgebra Linear.3&ordf;. edi&ccedil;&atilde;o.Editora Harbra ltda.1986.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Camargo, I. e Boulos, P. Geometria Anal&iacute;tica um Tratamento Vetorial. 3&ordf;. Edi&ccedil;&atilde;o. S&atilde;o Paulo, Pearson &ndash;Prentice Hall Editora. 2005. &nbsp;<br />\r\nRefer&ecirc;ncias Complementares:<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Roberto de Barros Lima. Elementos de Geometria Anal&iacute;tica. Companhia Editora Nacional, 4a edi&ccedil;&atilde;o,1973.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Antonio dos Santos Machado. Algebra Linear e Geometria Anal&iacute;tica. Atual editora, 2a edi&ccedil;&atilde;o, 1995.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Z&oacute;zimo M. Gon&ccedil;alves. Curso de Geometria Anal&iacute;tica. Editora Cient&iacute;fica, 1969.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;David C. Murdoch. Geometria Anal&iacute;tica. LTC, 2a edition, 1978.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Steinbruch and P. Winterle. Geometria Anal&iacute;tica. McGRAW-HILL, 2a edition, 1987.</p>','0','303','15','0','25'),('10585','MC732','Projeto de Sistemas Computacionais','4','G','5','0','<p style=\"text-align: justify;\">Uma introdu&ccedil;&atilde;o &agrave; arquitetura e organiza&ccedil;&atilde;o de computadores. Tecnologias e perspectiva hist&oacute;rica. Medidas de desempenho. Conjunto de instru&ccedil;&otilde;es. Mem&oacute;ria. Unidades de aritm&eacute;tica e l&oacute;gica. Projeto b&aacute;sico de um processador. Pipeline. Hierarquia da mem&oacute;ria: cache e mem&oacute;ria virtual. Dispositivos de Entrada/Sa&iacute;da.</p>','<p>- David A. Patterson and John L. Hennessy. Computer Organization and Design: The Hardware/Software Interface. Morgan Kaufmann, 5th Edition, 2013</p>','0','9','2','0','16'),('10586','MC832','Redes de Computadores','4','G','5','0','<p>Redes de Computadores e a Internet. Terminologia e aplica&ccedil;&otilde;es, topologias, modelos de arquitetura e protocolos. Camadas de Aplica&ccedil;&atilde;o, Transporte, Rede, Enlace e F&iacute;sica. Redes sem Fio.</p>','<ul>\r\n	<li>Computer Networking: a top-down Approach, James F. Kurose and Keith W. Ross; Pearson, 6th Edition (2012)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>Computer Networks, Andrew S. Tanenbaum; Pearson, 5th Edition (2010)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>Internetworking with TCP/IP Volume One, by Douglas E. Comer; Pearson, 6th Edition (2013)</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>','0','6','0','0','16'),('13553','MA021',NULL,NULL,'G',NULL,'0',NULL,NULL,'0','0','0','0',NULL),('13557','MA131',NULL,NULL,'G',NULL,'0',NULL,NULL,'0','0','0','0',NULL),('14220','ME210','Historiografia e Ensino de História','4','S',NULL,'0','<p>Estudo das diferentes acep&ccedil;&otilde;es do termo historiografia e problematiza&ccedil;&atilde;o do m&eacute;todo da cr&iacute;tica historiogr&aacute;fica. A historiografia e o debate do narrativismo: compet&ecirc;ncia narrativa, experi&ecirc;ncia e consci&ecirc;ncia, mem&oacute;ria e hist&oacute;ria. Reflex&atilde;o sobre as escolas hist&oacute;ricas e seus referenciais te&oacute;ricos, metodol&oacute;gicos e epistemol&oacute;gicos. O ensino de hist&oacute;ria no Brasil e seus pressupostos historiogr&aacute;ficos entre os s&eacute;culos XIX e XXI. Problematiza&ccedil;&atilde;o da no&ccedil;&atilde;o de did&aacute;tica da hist&oacute;ria. A diversidade do ensino de hist&oacute;ria para al&eacute;m do espa&ccedil;o escolar. A Hist&oacute;ria ensinada e a constitui&ccedil;&atilde;o da mem&oacute;ria social.</p>','<p>AMADO, Jana&iacute;na &amp; FERREIRA, Marieta de Moraes. Usos &amp; Abusos da Hist&oacute;ria Oral. Rio de Janeiro: Funda&ccedil;&atilde;o Getulio Vargas, 1998. ARIST&Oacute;TELES. Po&eacute;tica. tradu&ccedil;&atilde;o de Eudoro de Sousa. 5 ed. Imprensa Nacional, Casa da Moeda, 1998. AR&Oacute;STEGUI, J&uacute;lio. A pesquisa hist&oacute;rica: teoria e m&eacute;todo. Bauru, SP: Edusc, 2006. BITTENCOURT, Circe M. F. Ensino de Hist&oacute;ria: fundamentos e m&eacute;todos. S&atilde;o Paulo: Cortez, 2004. BOUTIER, Jean e JULIA, Dominique. (Orgs.). Passados Recompostos: campos e canteiros da hist&oacute;ria. Rio de Janeiro, Editora UFRJ; Editora FGV, 1998. BURKE, Peter. A Escrita da Hist&oacute;ria: Novas perspectivas. S&atilde;o Paulo. Editora da Unesp, 1992. ____________. A Escola dos Annales (1929-1989) A revolu&ccedil;&atilde;o francesa da Historiografia. S&atilde;o Paulo, EDUNESP, 1997. BLOCH, Marc. Apologia da Hist&oacute;ria &ndash; ou o of&iacute;cio do historiador. Trad. Andr&eacute; Telles. Rio de Janeiro. Jorge Zahar Ed., 2001. CARDOSO, Ciro F.&amp; VAINFAS, Ronaldo. Os dom&iacute;nios da Hist&oacute;ria: ensaio de teoria e metodologia. Rio de Janeiro, Campus, 1997. CHARTIER, Roger. &Agrave; Beira da Fal&eacute;sia: a hist&oacute;ria entre certezas e inquietude. Porto Alegre: Editora da UFRGS, 2002. DE CERTEAU, Michel. A escrita da Hist&oacute;ria. Rio de Janeiro, Forense Universit&aacute;ria, 2008. FERNANDES, Florestan (Org.) FEBVRE: Hist&oacute;ria. S&atilde;o Paulo, &Aacute;tica, 1992. FINLEY, Moses I. Uso e abuso da Hist&oacute;ria. S&atilde;o Paulo. Martins Fontes, 1989. FONTANA, Josep. A hist&oacute;ria dos homens. Trad. Helo&iacute;sa Jochims Reichel e Marcelo F. da Costa. Bauru, S&atilde;o Paulo: Edusc, 2004. FOUCAULT, Michel. A Ordem do Discurso. Tradu&ccedil;&atilde;o de Laura de Almeida Sampaio. 6&ordf; ed. S&atilde;o Paulo: Loyola, 1998. GARDINER, Patrick. (Org.). Teorias da Hist&oacute;ria. 3 ed. Lisboa: Calouste Gulbenkian, 1984. GAUTHIER, Clermont e TARDIF, Maurice. O saber profissional dos professores: fundamentos e epistemologia. Trad. Francisco A. Loiola. Quebec:Universidade Laval, 1996. HOLANDA, S&eacute;rgio Buarque (Org.) RANKE, Leopold Von: hist&oacute;ria. S&atilde;o Paulo: &Aacute;tica, 1979. LE GOFF, Jacques. Hist&oacute;ria e mem&oacute;ria. Campinas, S&atilde;o Paulo, Editora da UNICAMP, 1996. REIS, Jos&eacute; Carlos. Hist&oacute;ria e teoria: Historicismo, modernidade, temporalidade e verdade. Rio de Janeiro, Editora FGV, 2005. RICOEUR, PAUL. Tempo e narrativa: a intriga e a narrativa hist&oacute;rica. S&atilde;o Paulo: Editora Martins Fontes, 2010.&nbsp;______________. Tempo e Narrativa: a configura&ccedil;&atilde;o do tempo na narrativa de fic&ccedil;&atilde;o. S&atilde;o Paulo: Editora Martins Fontes, 2010. RIOUX, Jean Pierre &amp; SIRINELLI, Jean- Fran&ccedil;ois. Para uma Hist&oacute;ria cultural. Lisboa, Editorial Estampa, 1998. R&Uuml;SEN, J&ouml;rn. Raz&atilde;o hist&oacute;rica: teoria da hist&oacute;ria: fundamentos da ci&ecirc;ncia hist&oacute;rica. Trad. de Estev&atilde;o de Resende Martins. &ndash;Bras&iacute;lia: Editora Universidade de Bras&iacute;lia, 2010. __________. Reconstru&ccedil;&atilde;o do passado. Trad. de Asta-Rose Alcaide. Bras&iacute;lia: Editora Universidade de Bras&iacute;lia, 2010. __________. Hist&oacute;ria viva: teoria da hist&oacute;ria: formas e fun&ccedil;&otilde;es do conhecimento hist&oacute;rico. Estev&atilde;o de Resende Martins. &ndash;Bras&iacute;lia: Editora Universidade de Bras&iacute;lia, 2010. WHITE, Hayden. Meta-Hist&oacute;ria: a imagina&ccedil;&atilde;o hist&oacute;rica no s&eacute;culo XIX. S&atilde;o Paulo: EDUSP, 1992.</p>','0','0','0','0','19'),('16121','ME203','Educação Patrimonial e Ensino de História','4','S',NULL,'0','<p>O ensino de Hist&oacute;ria e o campo do Patrim&ocirc;nio Cultural material e imaterial. Explora&ccedil;&atilde;o das conex&otilde;es das institui&ccedil;&otilde;es de mem&oacute;ria com os campos da cultura, do mercado, da ci&ecirc;ncia e da educa&ccedil;&atilde;o. A partir de estudos de caso e de levantamentos gerais sobre a situa&ccedil;&atilde;o dos museus brasileiros, s&atilde;o examinadas as novas concep&ccedil;&otilde;es de ensino de Hist&oacute;ria nos museus trazidas pela discuss&atilde;o contempor&acirc;nea sobre patrim&ocirc;nio, mem&oacute;ria, identidade cultural e educa&ccedil;&atilde;o.</p>','<p>ABREU, Regina. CHAGAS, M&aacute;rio (orgs.). Mem&oacute;ria e Patrim&ocirc;nio: ensaios contempor&acirc;neos. Rio de Janeiro: Lamparina, 2009. ANDERSON, Benedict. Comunidades Imaginadas. S&atilde;o Paulo: Companhia das Letras, 2008. CHUVA, M&aacute;rcia. Os arquitetos da mem&oacute;ria: sociog&ecirc;nese das pr&aacute;ticas de preserva&ccedil;&atilde;o do patrim&ocirc;nio cultural no Brasil (1930-1940). Rio de Janeiro: ed. UFRJ, 2009. CASTRIOTA, Leonardo. Patrim&ocirc;nio Cultural: conceitos, pol&iacute;ticas e instrumentos. S&atilde;o Paulo: Annablume, 2009. CHOAY, Francoise. A alegoria do patrim&ocirc;nio. S&atilde;o Paulo: UNESCO, 2001. FARGE, Arlette. Lugares para a hist&oacute;ria. Belo Horizonte: Aut&ecirc;ntica, 2011. OLIVEIRA, Lucia Lippi. Cultura &eacute; Patrim&ocirc;nio: um guia. Rio de Janeiro: FGV, 2009. SALVADORI, Maria &Acirc;ngela Borges. Hist&oacute;ria, Ensino e Patrim&ocirc;nio. Araraquara, SP: Junqueira &amp; Marin Editores, 2010. SANTOS, Myrian Sep&uacute;lveda dos. Museus brasileiros e pol&iacute;tica cultural. Revista Brasileira de Ci&ecirc;ncias Sociais 19 (55): 53-73, jun. 2004. SCHMIDT, Maria Auxiliadora; BARCA, Isabel. Aprender Hist&oacute;ria: Perspectivas da Educa&ccedil;&atilde;o Hist&oacute;rica. Iju&iacute;: Uniju&iacute;, 2009. SOARES, Andre Luis Ramos; KLAMT, Sergio. Educa&ccedil;&atilde;o Patrimonial: teoria e pr&aacute;tica. Santa Maria: Editora da UFSM, 2007.</p>','0','0','0','0',NULL),('17180','EE533','Eletrônica Básica I','4','G',NULL,'0','<p>Conceitos de projeto. Amplificadores operacionais ideais. Circuitos com amplificadores operacionais. Diodos semicondutores. Transistores de efeito de campo MOS. Transistores bipolares. Amplificadores de pot&ecirc;ncia e fontes de alimenta&ccedil;&atilde;o. Conceitos e aplica&ccedil;&otilde;es de eletr&ocirc;nica digital. Projeto final.</p>','<p><span style=\"color:rgb(68, 68, 68)\">RODEN, S. &amp; CARPENTER, G.L. Electronic Design:From Concept to Reality. Discovery Press, 1997. SEDRA, S. &amp; SMITH, K.C. Microelectronic Circuits. Oxford University Press, 1998 MILLMAN,A. &amp; GRABEL. Microelectronics. Mc Graw Hill, 1987. BAR-LEV, A. Semiconductors and Electronic Devices. Prentice Hall, 1993. ANTOGNETTI, G.M. Semiconductor Devices Modelling with Spice. McGraw-Hill, 1998 HOROWITZ, P. &amp; HILL, W. The Art of Electronics. Cambrige University Press, 1990.</span></p>','0','0','0','0',NULL),('18282','F 259','Introdução à Física Experimental II','2','G',NULL,'0','<p>Produ&ccedil;&atilde;o de gr&aacute;ficos em computador; Lineariza&ccedil;&atilde;o de modelos n&atilde;o-lineares; Ajuste linear por software;&nbsp;Coleta de dados a partir da an&aacute;lise de um v&iacute;deo; Desvios sistem&aacute;ticos nos dados; Uso de instrumentos de&nbsp;medi&ccedil;&atilde;o de grandezas eletromagn&eacute;ticas e termodin&acirc;micas; Medi&ccedil;&otilde;es e curvas de calibra&ccedil;&atilde;o; Coleta&nbsp;automatizada de dados; Testes e compara&ccedil;&atilde;o de modelos; Trabalho em equipe e &eacute;tica cient&iacute;fica.</p>','<p>Refer&ecirc;ncias b&aacute;sicas:<br />\r\n&bull; &ldquo;Metrologia e incerteza de medi&ccedil;&atilde;o: conceitos e aplica&ccedil;&otilde;es&rdquo;, Alexandre Mendes e Pedro Paulo Novellino do Ros&aacute;rio, 1a edi&ccedil;&atilde;o<br />\r\n(LTC, 2020).<br />\r\n&bull; &quot;Fundamentos da Teoria de Erros&quot;, J. H. Vuolo, 2a edi&ccedil;&atilde;o (Blucher, 1996).<br />\r\n&bull; &quot;An introduction to uncertainty in measurement: Using the GUM (guide to the expression of uncertainty in measurement)&quot;, L.<br />\r\nKirkup and R . B. Frenkel (Cambridge University Press, 2006).<br />\r\nRefer&ecirc;ncias Complementares:<br />\r\n&bull; &ldquo;The Art of Experimental Physics&rdquo;, D. W. Preston and E. R. Dietz; John Wiley &amp; Sons, 1991<br />\r\n&bull; &ldquo;Experiments in Physics&quot;, D.W.Preston, John Wiley &amp; Sons, 1985<br />\r\n&bull; Fundamentos de F&iacute;sica - Volume 2- Gravita&ccedil;&atilde;o, Ondas e Termodin&acirc;mica. Robert Resnick (Autor), Jearl Walker (Autor), David<br />\r\nHalliday (Autor)</p>','0','0','0','0',NULL),('631','BE310','Ciências do Ambiente','2','G','5','0','<p>Popula&ccedil;&atilde;o humana e recursos naturais renov&aacute;veis e n&atilde;o renov&aacute;veis. Intera&ccedil;&atilde;o entre o homem e ambientes naturais ou constru&iacute;dos. Ambientes brasileiros terrestres e aqu&aacute;ticos. An&aacute;lise de ambientes: diagramas energ&eacute;ticos e modelos. O homem como modificador do ambiente. Popula&ccedil;&atilde;o, energia, clima, ecotoxicologia, extin&ccedil;&atilde;o, biodiversidade e sustentabilidade. Direito ecol&oacute;gico e pol&iacute;tica ambiental. Responsabilidade do profissional com rela&ccedil;&atilde;o &agrave; sociedade e ao ambiente.</p>','<p>Popula&ccedil;&atilde;o humana e recursos naturais renov&aacute;veis e n&atilde;o renov&aacute;veis. Intera&ccedil;&atilde;o entre o homem e ambientes naturais ou constru&iacute;dos. Ambientes brasileiros terrestres e aqu&aacute;ticos. An&aacute;lise de ambientes: diagramas energ&eacute;ticos e modelos. O homem como modificador do ambiente. Popula&ccedil;&atilde;o, energia, clima, ecotoxicologia, extin&ccedil;&atilde;o, biodiversidade e sustentabilidade. Direito ecol&oacute;gico e pol&iacute;tica ambiental. Responsabilidade do profissional com rela&ccedil;&atilde;o &agrave; sociedade e ao ambiente.</p>','0','3150','126','3','15'),('845','CE304','Direito','2','G','5','0','<p>Fundamento de direito p&uacute;blico e privado. Aplica&ccedil;&atilde;o de normas jur&iacute;dicas aos fatos econ&ocirc;micos.</p>','<p>BOBBIO, Norberto. <em>Da estrutura &agrave; fun&ccedil;&atilde;o: novos ensaios de teoria do direito</em>, S&atilde;o Paulo, Manole, 2007.</p>\r\n\r\n<p>CAMPILONGO, Celso. <em>O direito na sociedade complexa</em>, 2<sup>a</sup>. ed., S&atilde;o Paulo, 2011.</p>\r\n\r\n<p>FABIANI, Emerson R. (org.). <em>Impasses e aporias do direito contempor&acirc;neo: estudos em homenagem a Jos&eacute; Eduardo Faria</em>, S&atilde;o Paulo, Saraiva, 2011.</p>\r\n\r\n<p>FARIA, Jos&eacute; Eduardo. <em>O direito na economia globalizada</em>, S&atilde;o Paulo, Malheiros, 2004.</p>\r\n\r\n<p>FERRAZ JR., Tercio Sampaio. <em>Introdu&ccedil;&atilde;o ao estudo do direito: t&eacute;cnica, decis&atilde;o, domina&ccedil;&atilde;o</em>, 6<sup>a</sup>. ed. Revista e ampliada, S&atilde;o Paulo, Atlas, 2010.</p>\r\n\r\n<p>FONSECA, Jo&atilde;o Bosco Leopoldino da. Direito Econ&ocirc;mico. Ed.Forense.</p>\r\n\r\n<p>GRAU, Eros Roberto. A ordem econ&ocirc;mica na Constitui&ccedil;&atilde;o de 1988. Ed. Malheiros.</p>\r\n\r\n<p>KELSEN, Hans. <em>Teoria pura do direito</em>, S&atilde;o Paulo, WMF Martins Fontes, 2009.</p>\r\n\r\n<p>LAFER, Celso. <em>A reconstru&ccedil;&atilde;o dos direitos humanos</em>, S&atilde;o Paulo, Companhia das Letras, 1988.</p>\r\n\r\n<p>LENZA, Pedro , Direito Constitucional , Ed. Saraiva</p>\r\n\r\n<p>LOPES, Jos&eacute; Reinaldo de Lima. <em>O direito na hist&oacute;ria</em>, 3<sup>a</sup>. ed., S&atilde;o Paulo, Atlas, 2008.</p>\r\n\r\n<p>LUMIA, Giuseppe. <em>Elementos de teoria e de ideologia do direito</em>, S&atilde;o Paulo, Martins Fontes, 2003.</p>\r\n\r\n<p>MACEDO JUNIOR, Ronaldo Port